<?php
namespace Tests\Feature;
use App\Models\Products;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Hash;use Tests\TestCase;
class InventoryTest extends TestCase {use RefreshDatabase;public function test_manager_can_create_product():void{$user=User::create(['name'=>'Manager','email'=>'manager@example.com','password'=>Hash::make('password123'),'role'=>'manager','is_active'=>true]);$this->actingAs($user)->post('/products',['product_name'=>'Laptop','sku'=>'LAP-001','description'=>'Business laptop','product_price'=>2500000,'cost_price'=>2000000,'category'=>'Electronics','stock_quantity'=>10,'reorder_level'=>2])->assertRedirect('/products');$this->assertDatabaseHas('products',['sku'=>'LAP-001','stock_quantity'=>10]);$this->assertDatabaseHas('stock_movements',['type'=>'OPENING','quantity'=>10]);}public function test_staff_cannot_manage_products():void{$user=User::create(['name'=>'Staff','email'=>'staff@example.com','password'=>Hash::make('password123'),'role'=>'staff','is_active'=>true]);$this->actingAs($user)->get('/products/create')->assertForbidden();}}
